"use client";

// In-app turn-by-turn navigation — full-screen driver mode.
// Orchestrates: saved-route loading, navigation targets, GPS, the navigation
// engine, voice guidance, wake lock, stop completion, resume, and simulation.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import dynamic from "next/dynamic";
import { useRouter, useSearchParams } from "next/navigation";
import { format } from "date-fns";
import {
  Loader2,
  MapPin,
  Volume2,
  VolumeX,
  Maximize2,
  LocateFixed,
  X,
  AlertTriangle,
  CheckCircle2,
  Play,
  RotateCcw,
  ArrowLeft,
  Satellite,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import NavigationManeuverCard from "@/components/navigation-maneuver-card";
import NavigationBottomPanel from "@/components/navigation-bottom-panel";
import NavigationExitDialog from "@/components/navigation-exit-dialog";
import { useDriverLocation } from "@/hooks/use-driver-location";
import { useSpeechNavigation } from "@/hooks/use-speech-navigation";
import { useWakeLock } from "@/hooks/use-wake-lock";
import { useNavigationEngine } from "@/hooks/use-navigation-engine";
import {
  buildNavigationTargets,
  clearNavSession,
  loadNavSession,
  type NavigationTarget,
} from "@/lib/navigation";
import { FIXED_LOCATIONS } from "@/lib/route-model";
import type { OptimizedRouteResult } from "@/lib/vroom";
import type { PathPoint } from "@/lib/geo-utils";

// MapLibre must never render on the server
const NavigationMap = dynamic(() => import("@/components/navigation-map-maplibre"), {
  ssr: false,
  loading: () => (
    <div className="absolute inset-0 flex items-center justify-center bg-[#0b1417] text-muted-foreground">
      <Loader2 className="mr-2 h-5 w-5 animate-spin" /> Loading map…
    </div>
  ),
});

type Phase = "loading" | "no-route" | "not-started" | "confirm" | "nav" | "load-error";

interface LoadedRoute {
  status: string;
  routeData: OptimizedRouteResult;
}

const HOME_POS: PathPoint[] = [
  [FIXED_LOCATIONS.HOME.latitude, FIXED_LOCATIONS.HOME.longitude],
  [FIXED_LOCATIONS.HOME.latitude + 0.00005, FIXED_LOCATIONS.HOME.longitude + 0.00005],
];

export default function NavigationClient() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const date = searchParams.get("date") || format(new Date(), "yyyy-MM-dd");
  const simulate = searchParams.get("simulate") === "1";
  // Simulation speed in m/s (default ~40 km/h; capped at 120 m/s for fast dev testing)
  const simSpeed = Math.min(120, Math.max(2, Number(searchParams.get("speed")) || 11));

  const [phase, setPhase] = useState<Phase>("loading");
  const [loadError, setLoadError] = useState<string | null>(null);
  const [route, setRoute] = useState<LoadedRoute | null>(null);
  const [tokens, setTokens] = useState<Record<string, { token: string; completed: boolean }>>({});
  const [navWarnings, setNavWarnings] = useState<string[]>([]);
  const [resumeIndex, setResumeIndex] = useState<number | null>(null);
  const [startIndex, setStartIndex] = useState(0);
  const [doneIds, setDoneIds] = useState<Set<string>>(new Set());
  const [completing, setCompleting] = useState(false);
  const [completionError, setCompletionError] = useState<string | null>(null);
  const [exitOpen, setExitOpen] = useState(false);
  const [follow, setFollow] = useState(true);
  const [overviewRequest, setOverviewRequest] = useState(0);
  const [startingRoute, setStartingRoute] = useState(false);

  // -------------------------------------------------------------------------
  // Load the saved route for this date
  // -------------------------------------------------------------------------
  useEffect(() => {
    let cancelled = false;
    (async () => {
      setPhase("loading");
      try {
        const res = await fetch(`/api/route/navigation?date=${date}`, { cache: "no-store" });
        if (cancelled) return;
        if (res.status === 401) {
          router.push("/");
          return;
        }
        const data = await res.json();
        if (!res.ok) {
          setLoadError(data.error || "Failed to load the route.");
          setPhase("load-error");
          return;
        }
        if (!data.route) {
          setPhase("no-route");
          return;
        }
        setRoute({ status: data.route.status, routeData: data.route.routeData });
        setTokens(data.tokens || {});
        setPhase(data.route.status === "STARTED" ? "confirm" : "not-started");
      } catch {
        if (!cancelled) {
          setLoadError("Network error — could not reach the server.");
          setPhase("load-error");
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [date, router]);

  // -------------------------------------------------------------------------
  // Navigation targets from the optimized VROOM route
  // -------------------------------------------------------------------------
  const baseTargets = useMemo(() => {
    if (!route) return [] as NavigationTarget[];
    const completedOrderIds = new Set(
      Object.entries(tokens)
        .filter(([, v]) => v.completed)
        .map(([orderId]) => orderId)
    );
    const { targets, warnings } = buildNavigationTargets(route.routeData, { completedOrderIds });
    setNavWarnings(warnings);
    return targets;
  }, [route, tokens]);

  const targets = useMemo(
    () => baseTargets.map((t) => (doneIds.has(t.id) ? { ...t, completed: true } : t)),
    [baseTargets, doneIds]
  );

  // Check for a resumable session once targets are known
  useEffect(() => {
    if (phase !== "confirm" || targets.length === 0) return;
    const session = loadNavSession();
    if (session && session.date === date && session.activeTargetIndex > 0) {
      setResumeIndex(session.activeTargetIndex);
    } else {
      setResumeIndex(null);
    }
  }, [phase, targets.length, date]);

  // -------------------------------------------------------------------------
  // Hooks: speech, location, engine
  // -------------------------------------------------------------------------
  const speech = useSpeechNavigation();

  const engineRef = useRef<ReturnType<typeof useNavigationEngine> | null>(null);

  const [simulatePath, setSimulatePath] = useState<PathPoint[] | null>(simulate ? HOME_POS : null);
  const locationActive = phase === "confirm" || phase === "nav";
  const { fix, fixRef, status: gpsStatus } = useDriverLocation({
    enabled: locationActive,
    report: phase === "nav" && !simulate,
    reportExtra: { routeDate: date },
    simulatePath,
    simulateSpeed: simSpeed,
  });

  const engine = useNavigationEngine({
    targets,
    initialTargetIndex: startIndex,
    position: fix,
    active: phase === "nav",
    routeDate: date,
    speak: speech.speak,
    muted: speech.muted,
    onArrive: (t) => {
      try {
        navigator.vibrate?.([200, 100, 200]);
      } catch {
        /* unsupported */
      }
      speech.speak(`Arriving at ${t.title}`, { force: true });
    },
  });
  engineRef.current = engine;

  useWakeLock(phase === "nav" && engine.status !== "completed" && engine.status !== "error");

  // Simulation follows the active leg path once available
  useEffect(() => {
    if (!simulate) return;
    if (engine.leg && engine.leg.path.length >= 2) {
      setSimulatePath(engine.leg.path);
    }
  }, [simulate, engine.leg]);

  // Native GPS foreground service while navigating (Android WebView APK).
  // Supports both bridge flavors: AndroidBridge (startGpsTracking) and the
  // dev APK's AndroidGps (start(routeDate)/stop).
  useEffect(() => {
    if (phase !== "nav" || simulate) return;
    const w = window as unknown as {
      AndroidBridge?: { startGpsTracking?: () => void; stopGpsTracking?: () => void };
      AndroidGps?: { start?: (routeDate?: string) => void; stop?: () => void };
    };
    const usingBridge = !!w.AndroidBridge?.startGpsTracking;
    try {
      if (usingBridge) w.AndroidBridge!.startGpsTracking!();
      else w.AndroidGps?.start?.(date);
    } catch {
      /* not in APK */
    }
    return () => {
      try {
        if (usingBridge) w.AndroidBridge!.stopGpsTracking!();
        else w.AndroidGps?.stop?.();
      } catch {
        /* ignore */
      }
    };
  }, [phase, simulate, date]);

  // Clear stale session when the route completes
  useEffect(() => {
    if (engine.status === "completed") clearNavSession();
  }, [engine.status]);

  // -------------------------------------------------------------------------
  // Actions
  // -------------------------------------------------------------------------

  const beginNavigation = (index: number) => {
    speech.unlock();
    setStartIndex(index);
    setFollow(true);
    setPhase("nav");
  };

  const startRouteAndNavigate = async () => {
    if (!route) return;
    setStartingRoute(true);
    try {
      const res = await fetch("/api/route/save", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ date, routeData: route.routeData, status: "STARTED" }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setLoadError(data.error || "Failed to start the route.");
        return;
      }
      if (data.trackingTokens) {
        const map: Record<string, { token: string; completed: boolean }> = {};
        for (const t of data.trackingTokens as { orderId: string; token: string }[]) {
          map[t.orderId] = { token: t.token, completed: false };
        }
        setTokens((prev) => ({ ...map, ...prev }));
      }
      setPhase("confirm");
    } finally {
      setStartingRoute(false);
    }
  };

  /** Primary button: complete the active target. */
  const handlePrimaryAction = useCallback(async () => {
    const eng = engineRef.current;
    const target = eng?.activeTarget;
    if (!eng || !target) return;
    setCompletionError(null);

    if (target.kind === "pickup") {
      const tracking = target.orderId ? tokens[target.orderId] : undefined;
      if (!tracking?.token) {
        setCompletionError("No tracking link found for this stop — try refreshing, or skip it.");
        return;
      }
      setCompleting(true);
      try {
        const res = await fetch(`/api/track/${tracking.token}/complete`, { method: "POST" });
        if (!res.ok) {
          const data = await res.json().catch(() => ({}));
          setCompletionError(data.error || `Could not complete the pickup (HTTP ${res.status}). Tap to retry.`);
          return;
        }
        setTokens((prev) => ({ ...prev, [target.orderId!]: { ...prev[target.orderId!], completed: true } }));
      } catch {
        setCompletionError("Network error — pickup not saved yet. Tap to retry.");
        return;
      } finally {
        setCompleting(false);
      }
    }

    setDoneIds((prev) => new Set(prev).add(target.id));
    eng.confirmActiveTargetComplete();
  }, [tokens]);

  const handleExit = useCallback(() => {
    speech.stop();
    router.push("/route");
  }, [router, speech]);

  // -------------------------------------------------------------------------
  // Render helpers
  // -------------------------------------------------------------------------

  const initialCenter = useMemo(() => {
    const first = targets.find((t) => !t.completed);
    return first
      ? { lat: first.lat, lng: first.lng }
      : { lat: FIXED_LOCATIONS.HOME.latitude, lng: FIXED_LOCATIONS.HOME.longitude };
  }, [targets]);

  const activeStep = engine.leg?.steps[engine.currentStepIndex] ?? null;
  const nextStep = engine.leg?.steps[engine.currentStepIndex + 1] ?? null;
  const navigating = phase === "nav";
  const isLastTarget = engine.upcomingCount <= 1;

  // ---------- Full-screen states ----------

  if (phase === "loading") {
    return (
      <FullScreenMessage>
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
        <p className="mt-3 text-sm text-muted-foreground">Loading route for {date}…</p>
      </FullScreenMessage>
    );
  }

  if (phase === "no-route") {
    return (
      <FullScreenMessage>
        <MapPin className="h-10 w-10 text-primary/50" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">No saved route</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">
          There is no route saved for {date}. Optimize and start a route from the planner first.
        </p>
        <Button onClick={() => router.push("/route")} className="mt-5 gap-2 bg-primary text-primary-foreground">
          <ArrowLeft className="h-4 w-4" /> Back to Route Planner
        </Button>
      </FullScreenMessage>
    );
  }

  if (phase === "load-error") {
    return (
      <FullScreenMessage>
        <AlertTriangle className="h-10 w-10 text-destructive" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">Could not load route</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">{loadError}</p>
        <div className="mt-5 flex gap-2">
          <Button variant="outline" onClick={() => router.push("/route")} className="border-white/10 bg-white/5">
            Back
          </Button>
          <Button onClick={() => window.location.reload()} className="bg-primary text-primary-foreground">
            Retry
          </Button>
        </div>
      </FullScreenMessage>
    );
  }

  if (phase === "not-started") {
    return (
      <FullScreenMessage>
        <AlertTriangle className="h-10 w-10 text-amber-400" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">Route not started</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">
          The saved route for {date} exists but hasn&apos;t been started. Start it to enable
          navigation and customer live-tracking.
        </p>
        {loadError && <p className="mt-2 text-sm text-destructive">{loadError}</p>}
        <div className="mt-5 flex gap-2">
          <Button variant="outline" onClick={() => router.push("/route")} className="border-white/10 bg-white/5">
            Back
          </Button>
          <Button
            onClick={startRouteAndNavigate}
            disabled={startingRoute}
            className="gap-2 bg-primary text-primary-foreground"
          >
            {startingRoute ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />}
            Start Route
          </Button>
        </div>
      </FullScreenMessage>
    );
  }

  // ---------- Start / resume confirmation ----------
  if (phase === "confirm") {
    const upcoming = targets.filter((t) => !t.completed);
    return (
      <FullScreenMessage>
        <Satellite className="h-10 w-10 text-primary" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">Ready to navigate</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">
          {upcoming.length} stop{upcoming.length === 1 ? "" : "s"} remaining for {date}.
          {gpsStatus === "denied"
            ? " GPS permission is denied — navigation will start from Home."
            : gpsStatus === "active"
              ? " GPS locked."
              : " Waiting for GPS…"}
        </p>
        {navWarnings.length > 0 && (
          <div className="mt-3 max-w-xs rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
            {navWarnings.map((w, i) => (
              <p key={i}>⚠ {w}</p>
            ))}
          </div>
        )}
        <div className="mt-5 flex flex-col items-center gap-2">
          {resumeIndex !== null && resumeIndex > 0 && resumeIndex < upcoming.length ? (
            <>
              <Button onClick={() => beginNavigation(resumeIndex)} className="h-12 w-64 gap-2 bg-primary text-primary-foreground text-base">
                <Play className="h-5 w-5" /> Resume navigation
              </Button>
              <Button
                variant="outline"
                onClick={() => {
                  clearNavSession();
                  beginNavigation(0);
                }}
                className="h-12 w-64 gap-2 border-white/10 bg-white/5"
              >
                <RotateCcw className="h-4 w-4" /> Start from beginning
              </Button>
            </>
          ) : (
            <Button onClick={() => beginNavigation(0)} className="h-12 w-64 gap-2 bg-primary text-primary-foreground text-base">
              <Play className="h-5 w-5" /> Start navigation
            </Button>
          )}
          <Button variant="ghost" onClick={() => router.push("/route")} className="text-muted-foreground">
            Back to planner
          </Button>
        </div>
        {simulate && (
          <p className="mt-4 rounded bg-primary/10 px-2 py-1 text-[0.625rem] font-bold uppercase tracking-wider text-primary">
            Simulation mode — GPS is simulated, nothing is reported
          </p>
        )}
      </FullScreenMessage>
    );
  }

  // ---------- Completed ----------
  if (engine.status === "completed") {
    return (
      <FullScreenMessage>
        <div className="flex h-20 w-20 items-center justify-center rounded-full bg-primary/15">
          <CheckCircle2 className="h-12 w-12 text-primary" />
        </div>
        <h1 className="mt-4 text-2xl font-bold text-foreground">Route Complete!</h1>
        <p className="mt-1 text-sm text-muted-foreground">Great work out there, HERO.</p>
        <div className="mt-5 grid grid-cols-3 gap-2">
          <div className="rounded-lg border border-white/10 bg-white/5 px-4 py-3 text-center">
            <div className="text-[0.625rem] uppercase tracking-wider text-muted-foreground">Stops</div>
            <div className="text-xl font-bold text-foreground">{engine.completedCount}/{engine.totalTargets}</div>
          </div>
          <div className="rounded-lg border border-white/10 bg-white/5 px-4 py-3 text-center">
            <div className="text-[0.625rem] uppercase tracking-wider text-muted-foreground">Distance</div>
            <div className="text-xl font-bold text-foreground">{((route?.routeData.totalDistanceMeters ?? 0) / 1000).toFixed(1)}<span className="text-xs"> km</span></div>
          </div>
          <div className="rounded-lg border border-white/10 bg-white/5 px-4 py-3 text-center">
            <div className="text-[0.625rem] uppercase tracking-wider text-muted-foreground">Planned</div>
            <div className="text-xl font-bold text-foreground">{Math.round((route?.routeData.totalDurationSeconds ?? 0) / 60)}<span className="text-xs"> min</span></div>
          </div>
        </div>
        <div className="mt-6 flex gap-2">
          <Button onClick={() => router.push("/route")} className="h-12 gap-2 bg-primary text-primary-foreground">
            <ArrowLeft className="h-4 w-4" /> Back to Route
          </Button>
          <Button variant="outline" onClick={() => router.push("/")} className="h-12 border-white/10 bg-white/5">
            Close
          </Button>
        </div>
      </FullScreenMessage>
    );
  }

  // ---------- Navigation mode ----------
  return (
    <div className="fixed inset-0 h-dvh w-full overflow-hidden bg-[#0b1417]">
      {/* Map */}
      <NavigationMap
        fixRef={fixRef}
        leg={engine.leg}
        progressMeters={engine.progressMeters}
        targets={targets}
        activeTargetId={engine.activeTarget?.id ?? null}
        completedIds={doneIds}
        follow={follow}
        onFollowChange={setFollow}
        overviewRequest={overviewRequest}
        initialCenter={initialCenter}
      />

      {/* Top: maneuver card + warnings */}
      <div
        className="absolute inset-x-0 top-0 z-10 space-y-2 px-3"
        style={{ paddingTop: "max(0.75rem, env(safe-area-inset-top))" }}
      >
        <NavigationManeuverCard
          step={activeStep}
          nextStep={nextStep}
          distanceToManeuver={engine.distanceToManeuver}
          offRoute={engine.offRoute}
          rerouting={engine.status === "rerouting"}
          offline={engine.leg?.offline ?? false}
        />
        {(engine.status === "requesting-directions") && (
          <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-[#0b1417]/95 px-4 py-2.5 text-sm text-[#c9d9d6] backdrop-blur-md">
            <Loader2 className="h-4 w-4 animate-spin text-primary" /> Getting directions…
          </div>
        )}
        {engine.warning && (
          <div className="flex items-start gap-2 rounded-xl border border-amber-500/30 bg-amber-500/15 px-4 py-2.5 text-xs text-amber-200 backdrop-blur-md">
            <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
            <span className="flex-1">{engine.warning}</span>
            <button onClick={engine.clearWarning} aria-label="Dismiss warning" className="shrink-0 text-amber-200/70 hover:text-amber-200">
              <X className="h-4 w-4" />
            </button>
          </div>
        )}
        {gpsStatus === "denied" && (
          <div className="rounded-xl border border-destructive/40 bg-destructive/15 px-4 py-2.5 text-xs text-destructive backdrop-blur-md">
            GPS permission denied — enable location for accurate guidance.
          </div>
        )}
        {simulate && (
          <div className="w-fit rounded bg-primary/15 px-2 py-1 text-[0.625rem] font-bold uppercase tracking-wider text-primary">
            Simulation
            {fix && (
              <span className="ml-1.5 font-mono normal-case text-primary/80">
                {fix.lat.toFixed(5)},{fix.lng.toFixed(5)} · {engine.status}
              </span>
            )}
          </div>
        )}
      </div>

      {/* Floating controls (right edge) */}
      <div
        className="absolute right-3 z-10 flex flex-col gap-2"
        style={{ top: "calc(max(0.75rem, env(safe-area-inset-top)) + 7.5rem)" }}
      >
        {!follow && (
          <FabButton label="Recenter" onClick={() => setFollow(true)} highlight>
            <LocateFixed className="h-5 w-5" />
          </FabButton>
        )}
        <FabButton
          label={speech.muted ? "Unmute voice guidance" : "Mute voice guidance"}
          onClick={() => speech.setMuted(!speech.muted)}
        >
          {speech.muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
        </FabButton>
        <FabButton
          label="Overview"
          onClick={() => {
            setFollow(false);
            setOverviewRequest((n) => n + 1);
          }}
        >
          <Maximize2 className="h-5 w-5" />
        </FabButton>
        <FabButton label="Exit navigation" onClick={() => setExitOpen(true)} danger>
          <X className="h-5 w-5" />
        </FabButton>
      </div>

      {/* Bottom panel */}
      {engine.activeTarget && (
        <div className="absolute inset-x-0 bottom-0 z-10">
          <NavigationBottomPanel
            target={engine.activeTarget}
            isLastTarget={isLastTarget}
            stopIndex={engine.completedCount + 1}
            totalTargets={engine.totalTargets}
            completedCount={engine.completedCount}
            arrived={engine.status === "arrived"}
            etaMs={engine.etaMs}
            remainingMeters={engine.remainingMeters}
            remainingSeconds={engine.remainingSeconds}
            completing={completing}
            completionError={completionError}
            onPrimaryAction={handlePrimaryAction}
            onSkip={() => engine.skipActiveTarget()}
          />
        </div>
      )}

      <NavigationExitDialog open={exitOpen} onOpenChange={setExitOpen} onConfirmExit={handleExit} />
    </div>
  );
}

function FabButton({
  children,
  label,
  onClick,
  highlight,
  danger,
}: {
  children: React.ReactNode;
  label: string;
  onClick: () => void;
  highlight?: boolean;
  danger?: boolean;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      title={label}
      onClick={onClick}
      className={`flex h-12 w-12 items-center justify-center rounded-full border shadow-lg shadow-black/40 backdrop-blur-md transition-transform active:scale-90 ${
        highlight
          ? "border-primary/50 bg-primary text-primary-foreground"
          : danger
            ? "border-white/10 bg-[#0b1417]/90 text-destructive hover:bg-[#0b1417]"
            : "border-white/10 bg-[#0b1417]/90 text-[#c9d9d6] hover:bg-[#0b1417]"
      }`}
    >
      {children}
    </button>
  );
}

function FullScreenMessage({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex h-dvh w-full flex-col items-center justify-center bg-background px-6 text-center">
      {children}
    </div>
  );
}

text:
"use client";

// MapLibre GL JS navigation surface — client-only (dynamically imported with
// ssr: false by the caller). Open-source stack only: OpenStreetMap tiles,
// no Google Maps, no Mapbox token.
//
// - Vector style via NEXT_PUBLIC_MAP_STYLE_URL when configured, otherwise a
//   built-in OSM raster style with proper attribution.
// - Optional 3D buildings fill-extrusion when the vector style exposes a
//   building layer (NEXT_PUBLIC_ENABLE_3D_BUILDINGS).
// - Optional dark cockpit filter applied to the map canvas only
//   (NEXT_PUBLIC_MAP_DARK_FILTER) — UI overlays are unaffected.
// - 3D third-person follow camera (pitch ~62°, zoom ~17, bearing follows
//   travel direction), smoothed vehicle orb marker with heading cone.

import { useEffect, useRef } from "react";
import * as maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import {
  bearingAlongPath,
  lerpBearing,
  lerpLatLng,
  pointAlongPath,
  type LatLng,
  type PathPoint,
} from "@/lib/geo-utils";
import type { NavLeg } from "@/hooks/use-navigation-engine";
import type { NavigationTarget } from "@/lib/navigation";
import type { DriverFix } from "@/hooks/use-driver-location";

const MAP_STYLE_URL = process.env.NEXT_PUBLIC_MAP_STYLE_URL || "";
const MAP_ATTRIBUTION = process.env.NEXT_PUBLIC_MAP_ATTRIBUTION || "© OpenStreetMap contributors";
const ENABLE_3D_BUILDINGS = (process.env.NEXT_PUBLIC_ENABLE_3D_BUILDINGS || "true") === "true";
const MAP_DARK_FILTER = (process.env.NEXT_PUBLIC_MAP_DARK_FILTER || "true") === "true";

const FOLLOW_PITCH = 62;
const FOLLOW_ZOOM = 17;

const ROUTE_COLOR = "#2dd4bf"; // teal-400 — matches Sidekick primary
const ROUTE_CASING = "#042f2e";
const ROUTE_PASSED = "rgba(15, 23, 42, 0.85)";

function fallbackRasterStyle(): maplibregl.StyleSpecification {
  return {
    version: 8,
    sources: {
      osm: {
        type: "raster",
        tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
        tileSize: 256,
        attribution: MAP_ATTRIBUTION,
      },
    },
    layers: [{ id: "osm-raster", type: "raster", source: "osm" }],
  };
}

export interface NavigationMapProps {
  /** Mutable ref to the latest driver fix (read inside the rAF loop). */
  fixRef: React.RefObject<DriverFix | null>;
  /** Active leg (route line + bounds). */
  leg: NavLeg | null;
  /** Along-path progress in meters — drives the dimmed "passed" segment. */
  progressMeters: number;
  /** All navigation targets (markers). */
  targets: NavigationTarget[];
  activeTargetId: string | null;
  completedIds: ReadonlySet<string>;
  /** Camera follow mode. */
  follow: boolean;
  onFollowChange: (follow: boolean) => void;
  /** Increment to trigger a fit-bounds overview. */
  overviewRequest: number;
  /** Initial map center when no GPS yet. */
  initialCenter: LatLng;
}

export default function NavigationMapMaplibre({
  fixRef,
  leg,
  progressMeters,
  targets,
  activeTargetId,
  completedIds,
  follow,
  onFollowChange,
  overviewRequest,
  initialCenter,
}: NavigationMapProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const vehicleRef = useRef<maplibregl.Marker | null>(null);
  const vehicleElRef = useRef<HTMLDivElement | null>(null);
  const stopMarkersRef = useRef<maplibregl.Marker[]>([]);
  const smoothedRef = useRef<{ pos: LatLng; bearing: number; initialized: boolean }>({
    pos: initialCenter,
    bearing: 0,
    initialized: false,
  });
  const followRef = useRef(follow);
  const legRef = useRef(leg);
  const progressRef = useRef(progressMeters);
  const lastPassedUpdateRef = useRef(-Infinity);

  followRef.current = follow;
  legRef.current = leg;
  progressRef.current = progressMeters;

  // -------------------------------------------------------------------------
  // Map init (once)
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: MAP_STYLE_URL || fallbackRasterStyle(),
      center: [initialCenter.lng, initialCenter.lat],
      zoom: 15,
      pitch: 0,
      bearing: 0,
      attributionControl: { compact: false },
      logoPosition: "bottom-left",
    });
    mapRef.current = map;
    // Debug/testing handle (also used by the ?simulate=1 helper)
    (window as unknown as { __navMap?: maplibregl.Map }).__navMap = map;

    // Graceful fallback: if a custom vector style fails to load, use raster OSM
    let styleLoaded = false;
    const onError = () => {
      if (!styleLoaded && MAP_STYLE_URL) {
        try {
          map.setStyle(fallbackRasterStyle());
        } catch {
          /* ignore */
        }
      }
    };
    map.on("error", onError);

    map.on("load", () => {
      styleLoaded = true;
      tryAdd3DBuildings(map);
      // Route sources + layers (empty initially)
      map.addSource("nav-route", {
        type: "geojson",
        data: { type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: [] } },
      });
      map.addSource("nav-route-passed", {
        type: "geojson",
        data: { type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: [] } },
      });
      map.addLayer({
        id: "nav-route-casing",
        type: "line",
        source: "nav-route",
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": ROUTE_CASING, "line-width": 9, "line-opacity": 0.9 },
      });
      map.addLayer({
        id: "nav-route-line",
        type: "line",
        source: "nav-route",
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": ROUTE_COLOR, "line-width": 5, "line-opacity": 0.95 },
      });
      map.addLayer({
        id: "nav-route-passed-line",
        type: "line",
        source: "nav-route-passed",
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": ROUTE_PASSED, "line-width": 5, "line-opacity": 0.9 },
      });

      // Vehicle orb marker
      const el = document.createElement("div");
      el.className = "nav-vehicle";
      el.innerHTML = `<div class="nav-vehicle-cone"></div><div class="nav-vehicle-orb"></div>`;
      vehicleElRef.current = el;
      const marker = new maplibregl.Marker({ element: el, anchor: "center" })
        .setLngLat([initialCenter.lng, initialCenter.lat])
        .addTo(map);
      vehicleRef.current = marker;

      // Follow camera baseline
      map.setPitch(FOLLOW_PITCH);
      map.setZoom(FOLLOW_ZOOM);
    });

    // Manual pan disables follow mode
    map.on("dragstart", () => {
      if (followRef.current) onFollowChange(false);
    });

    return () => {
      map.remove();
      mapRef.current = null;
      vehicleRef.current = null;
      vehicleElRef.current = null;
      delete (window as unknown as { __navMap?: maplibregl.Map }).__navMap;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Re-attempt 3D buildings after a style swap (fallback → no building layer, no-op)
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const onStyleData = () => tryAdd3DBuildings(map);
    map.on("styledata", onStyleData);
    return () => {
      map.off("styledata", onStyleData);
    };
  }, []);

  // -------------------------------------------------------------------------
  // Route line + passed segment updates
  // -------------------------------------------------------------------------
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    const src = map.getSource("nav-route") as maplibregl.GeoJSONSource | undefined;
    if (!src) return;
    const coords = leg ? leg.path.map(([lat, lng]) => [lng, lat]) : [];
    src.setData({
      type: "Feature",
      properties: {},
      geometry: { type: "LineString", coordinates: coords },
    });
  }, [leg]);

  // Passed segment — throttled to meaningful progress changes
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    const src = map.getSource("nav-route-passed") as maplibregl.GeoJSONSource | undefined;
    if (!src) return;
    if (!leg || leg.offline || leg.path.length < 2) {
      src.setData({ type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: [] } });
      return;
    }
    if (Math.abs(progressMeters - lastPassedUpdateRef.current) < 15) return;
    lastPassedUpdateRef.current = progressMeters;

    // Split the path at progressMeters
    const cum = leg.cumDistances;
    let idx = 0;
    while (idx < cum.length - 1 && cum[idx + 1] < progressMeters) idx++;
    const passed: PathPoint[] = leg.path.slice(0, idx + 1);
    passed.push([pointAlongPath(leg.path, cum, progressMeters).lat, pointAlongPath(leg.path, cum, progressMeters).lng]);
    src.setData({
      type: "Feature",
      properties: {},
      geometry: { type: "LineString", coordinates: passed.map(([lat, lng]) => [lng, lat]) },
    });
  }, [leg, progressMeters]);

  // -------------------------------------------------------------------------
  // Stop markers
  // -------------------------------------------------------------------------
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    for (const m of stopMarkersRef.current) m.remove();
    stopMarkersRef.current = [];

    for (const t of targets) {
      const el = document.createElement("div");
      const done = t.completed || completedIds.has(t.id);
      const isActive = t.id === activeTargetId;
      el.className = `nav-stop ${isActive ? "nav-stop-active" : ""} ${done ? "nav-stop-done" : ""}`;
      el.innerHTML =
        t.kind === "home"
          ? `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>`
          : t.kind === "dropoff"
            ? `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"/><path d="m3.3 7 8.7 5 8.7-5"/><path d="M12 22V12"/></svg>`
            : `<span>${t.stopNumber ?? ""}</span>`;
      const marker = new maplibregl.Marker({ element: el, anchor: "center" })
        .setLngLat([t.lng, t.lat])
        .addTo(map);
      stopMarkersRef.current.push(marker);
    }

    return () => {
      for (const m of stopMarkersRef.current) m.remove();
      stopMarkersRef.current = [];
    };
  }, [targets, activeTargetId, completedIds]);

  // -------------------------------------------------------------------------
  // Overview (fit active route bounds)
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (overviewRequest === 0) return;
    const map = mapRef.current;
    const currentLeg = legRef.current;
    if (!map || !currentLeg) return;
    const [[minLat, minLng], [maxLat, maxLng]] = currentLeg.bounds;
    map.fitBounds(
      [
        [minLng, minLat],
        [maxLng, maxLat],
      ],
      {
        padding: { top: 140, bottom: 300, left: 48, right: 48 },
        duration: 900,
        maxZoom: 16,
      }
    );
  }, [overviewRequest]);

  // When follow re-engages, snap back behind the vehicle
  useEffect(() => {
    if (!follow) return;
    const map = mapRef.current;
    if (!map) return;
    const s = smoothedRef.current;
    map.easeTo({
      center: [s.pos.lng, s.pos.lat],
      bearing: s.bearing,
      pitch: FOLLOW_PITCH,
      zoom: FOLLOW_ZOOM,
      duration: 600,
    });
  }, [follow]);

  // -------------------------------------------------------------------------
  // Animation loop: smooth vehicle marker + follow camera
  // -------------------------------------------------------------------------
  useEffect(() => {
    let raf = 0;
    let last = performance.now();

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = Math.min(0.1, (now - last) / 1000);
      last = now;
      const map = mapRef.current;
      const marker = vehicleRef.current;
      if (!map || !marker) return;

      const fix = fixRef.current;
      if (!fix) return;
      const s = smoothedRef.current;
      if (!s.initialized) {
        s.pos = { lat: fix.lat, lng: fix.lng };
        s.bearing = fix.heading ?? 0;
        s.initialized = true;
      }

      // Exponential smoothing toward the latest fix
      const k = 1 - Math.exp(-dt * 3.5);
      s.pos = lerpLatLng(s.pos, { lat: fix.lat, lng: fix.lng }, k);

      // Bearing: GPS heading when moving, else route bearing, else keep last
      let targetBearing = s.bearing;
      if (fix.heading !== null && (fix.speed === null || fix.speed > 1)) {
        targetBearing = fix.heading;
      } else {
        const currentLeg = legRef.current;
        if (currentLeg && !currentLeg.offline && currentLeg.path.length >= 2) {
          targetBearing = bearingAlongPath(currentLeg.path, currentLeg.cumDistances, progressRef.current);
        }
      }
      s.bearing = lerpBearing(s.bearing, targetBearing, 1 - Math.exp(-dt * 4));

      marker.setLngLat([s.pos.lng, s.pos.lat]);
      if (vehicleElRef.current) {
        vehicleElRef.current.style.transform = `rotate(${s.bearing}deg)`;
      }

      if (followRef.current && map.isStyleLoaded()) {
        map.jumpTo({
          center: [s.pos.lng, s.pos.lat],
          bearing: s.bearing,
          pitch: FOLLOW_PITCH,
          zoom: FOLLOW_ZOOM,
        });
      }
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      ref={containerRef}
      // Inline position/size beats MapLibre's `.maplibregl-map { position: relative }`
      // stylesheet rule, which would otherwise collapse the container to 0-height.
      style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}
      className={MAP_DARK_FILTER ? "nav-map-dark" : undefined}
      aria-label="Navigation map"
    />
  );
}

// ---------------------------------------------------------------------------
// 3D buildings — only when the loaded vector style exposes a building layer.
// Silently skips on raster fallback or styles without buildings.
// ---------------------------------------------------------------------------
function tryAdd3DBuildings(map: maplibregl.Map) {
  if (!ENABLE_3D_BUILDINGS) return;
  try {
    if (map.getLayer("sidekick-3d-buildings")) return;
    const style = map.getStyle();
    if (!style?.layers) return;
    const buildingLayer = style.layers.find(
      (l) =>
        (l as { "source-layer"?: string })["source-layer"] === "building" &&
        (l.type === "fill" || l.type === "fill-extrusion")
    ) as (maplibregl.LayerSpecification & { source?: string; "source-layer"?: string }) | undefined;
    if (!buildingLayer || !buildingLayer.source || !buildingLayer["source-layer"]) return;

    const before = style.layers.find((l) => l.type === "symbol")?.id;
    map.addLayer(
      {
        id: "sidekick-3d-buildings",
        type: "fill-extrusion",
        source: buildingLayer.source,
        "source-layer": buildingLayer["source-layer"],
        minzoom: 15,
        paint: {
          "fill-extrusion-color": "#1e293b",
          "fill-extrusion-opacity": 0.6,
          "fill-extrusion-height": [
            "coalesce",
            ["get", "render_height"],
            ["get", "height"],
            10,
          ] as unknown as maplibregl.ExpressionSpecification,
          "fill-extrusion-base": [
            "coalesce",
            ["get", "render_min_height"],
            ["get", "min_height"],
            0,
          ] as unknown as maplibregl.ExpressionSpecification,
        },
      } as maplibregl.LayerSpecification,
      before
    );
  } catch {
    /* 3D buildings are best-effort only */
  }
}

content.text:
"use client";

// MapLibre GL JS navigation surface — client-only (dynamically imported with
// ssr: false by the caller). Open-source stack only: OpenStreetMap tiles,
// no Google Maps, no Mapbox token.
//
// - Vector style via NEXT_PUBLIC_MAP_STYLE_URL when configured, otherwise a
//   built-in OSM raster style with proper attribution.
// - Optional 3D buildings fill-extrusion when the vector style exposes a
//   building layer (NEXT_PUBLIC_ENABLE_3D_BUILDINGS).
// - Optional dark cockpit filter applied to the map canvas only
//   (NEXT_PUBLIC_MAP_DARK_FILTER) — UI overlays are unaffected.
// - 3D third-person follow camera (pitch ~62°, zoom ~17, bearing follows
//   travel direction), smoothed vehicle orb marker with heading cone.

import { useEffect, useRef } from "react";
import * as maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import {
  bearingAlongPath,
  lerpBearing,
  lerpLatLng,
  pointAlongPath,
  type LatLng,
  type PathPoint,
} from "@/lib/geo-utils";
import type { NavLeg } from "@/hooks/use-navigation-engine";
import type { NavigationTarget } from "@/lib/navigation";
import type { DriverFix } from "@/hooks/use-driver-location";

const MAP_STYLE_URL = process.env.NEXT_PUBLIC_MAP_STYLE_URL || "";
const MAP_ATTRIBUTION = process.env.NEXT_PUBLIC_MAP_ATTRIBUTION || "© OpenStreetMap contributors";
const ENABLE_3D_BUILDINGS = (process.env.NEXT_PUBLIC_ENABLE_3D_BUILDINGS || "true") === "true";
const MAP_DARK_FILTER = (process.env.NEXT_PUBLIC_MAP_DARK_FILTER || "true") === "true";

const FOLLOW_PITCH = 62;
const FOLLOW_ZOOM = 17;

const ROUTE_COLOR = "#2dd4bf"; // teal-400 — matches Sidekick primary
const ROUTE_CASING = "#042f2e";
const ROUTE_PASSED = "rgba(15, 23, 42, 0.85)";

function fallbackRasterStyle(): maplibregl.StyleSpecification {
  return {
    version: 8,
    sources: {
      osm: {
        type: "raster",
        tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
        tileSize: 256,
        attribution: MAP_ATTRIBUTION,
      },
    },
    layers: [{ id: "osm-raster", type: "raster", source: "osm" }],
  };
}

export interface NavigationMapProps {
  /** Mutable ref to the latest driver fix (read inside the rAF loop). */
  fixRef: React.RefObject<DriverFix | null>;
  /** Active leg (route line + bounds). */
  leg: NavLeg | null;
  /** Along-path progress in meters — drives the dimmed "passed" segment. */
  progressMeters: number;
  /** All navigation targets (markers). */
  targets: NavigationTarget[];
  activeTargetId: string | null;
  completedIds: ReadonlySet<string>;
  /** Camera follow mode. */
  follow: boolean;
  onFollowChange: (follow: boolean) => void;
  /** Increment to trigger a fit-bounds overview. */
  overviewRequest: number;
  /** Initial map center when no GPS yet. */
  initialCenter: LatLng;
}

export default function NavigationMapMaplibre({
  fixRef,
  leg,
  progressMeters,
  targets,
  activeTargetId,
  completedIds,
  follow,
  onFollowChange,
  overviewRequest,
  initialCenter,
}: NavigationMapProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const vehicleRef = useRef<maplibregl.Marker | null>(null);
  const vehicleElRef = useRef<HTMLDivElement | null>(null);
  const stopMarkersRef = useRef<maplibregl.Marker[]>([]);
  const smoothedRef = useRef<{ pos: LatLng; bearing: number; initialized: boolean }>({
    pos: initialCenter,
    bearing: 0,
    initialized: false,
  });
  const followRef = useRef(follow);
  const legRef = useRef(leg);
  const progressRef = useRef(progressMeters);
  const lastPassedUpdateRef = useRef(-Infinity);

  followRef.current = follow;
  legRef.current = leg;
  progressRef.current = progressMeters;

  // -------------------------------------------------------------------------
  // Map init (once)
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: MAP_STYLE_URL || fallbackRasterStyle(),
      center: [initialCenter.lng, initialCenter.lat],
      zoom: 15,
      pitch: 0,
      bearing: 0,
      attributionControl: { compact: false },
      logoPosition: "bottom-left",
    });
    mapRef.current = map;
    // Debug/testing handle (also used by the ?simulate=1 helper)
    (window as unknown as { __navMap?: maplibregl.Map }).__navMap = map;

    // Graceful fallback: if a custom vector style fails to load, use raster OSM
    let styleLoaded = false;
    const onError = () => {
      if (!styleLoaded && MAP_STYLE_URL) {
        try {
          map.setStyle(fallbackRasterStyle());
        } catch {
          /* ignore */
        }
      }
    };
    map.on("error", onError);

    map.on("load", () => {
      styleLoaded = true;
      tryAdd3DBuildings(map);
      // Route sources + layers (empty initially)
      map.addSource("nav-route", {
        type: "geojson",
        data: { type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: [] } },
      });
      map.addSource("nav-route-passed", {
        type: "geojson",
        data: { type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: [] } },
      });
      map.addLayer({
        id: "nav-route-casing",
        type: "line",
        source: "nav-route",
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": ROUTE_CASING, "line-width": 9, "line-opacity": 0.9 },
      });
      map.addLayer({
        id: "nav-route-line",
        type: "line",
        source: "nav-route",
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": ROUTE_COLOR, "line-width": 5, "line-opacity": 0.95 },
      });
      map.addLayer({
        id: "nav-route-passed-line",
        type: "line",
        source: "nav-route-passed",
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": ROUTE_PASSED, "line-width": 5, "line-opacity": 0.9 },
      });

      // Vehicle orb marker
      const el = document.createElement("div");
      el.className = "nav-vehicle";
      el.innerHTML = `<div class="nav-vehicle-cone"></div><div class="nav-vehicle-orb"></div>`;
      vehicleElRef.current = el;
      const marker = new maplibregl.Marker({ element: el, anchor: "center" })
        .setLngLat([initialCenter.lng, initialCenter.lat])
        .addTo(map);
      vehicleRef.current = marker;

      // Follow camera baseline
      map.setPitch(FOLLOW_PITCH);
      map.setZoom(FOLLOW_ZOOM);
    });

    // Manual pan disables follow mode
    map.on("dragstart", () => {
      if (followRef.current) onFollowChange(false);
    });

    return () => {
      map.remove();
      mapRef.current = null;
      vehicleRef.current = null;
      vehicleElRef.current = null;
      delete (window as unknown as { __navMap?: maplibregl.Map }).__navMap;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Re-attempt 3D buildings after a style swap (fallback → no building layer, no-op)
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const onStyleData = () => tryAdd3DBuildings(map);
    map.on("styledata", onStyleData);
    return () => {
      map.off("styledata", onStyleData);
    };
  }, []);

  // -------------------------------------------------------------------------
  // Route line + passed segment updates
  // -------------------------------------------------------------------------
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    const src = map.getSource("nav-route") as maplibregl.GeoJSONSource | undefined;
    if (!src) return;
    const coords = leg ? leg.path.map(([lat, lng]) => [lng, lat]) : [];
    src.setData({
      type: "Feature",
      properties: {},
      geometry: { type: "LineString", coordinates: coords },
    });
  }, [leg]);

  // Passed segment — throttled to meaningful progress changes
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    const src = map.getSource("nav-route-passed") as maplibregl.GeoJSONSource | undefined;
    if (!src) return;
    if (!leg || leg.offline || leg.path.length < 2) {
      src.setData({ type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: [] } });
      return;
    }
    if (Math.abs(progressMeters - lastPassedUpdateRef.current) < 15) return;
    lastPassedUpdateRef.current = progressMeters;

    // Split the path at progressMeters
    const cum = leg.cumDistances;
    let idx = 0;
    while (idx < cum.length - 1 && cum[idx + 1] < progressMeters) idx++;
    const passed: PathPoint[] = leg.path.slice(0, idx + 1);
    passed.push([pointAlongPath(leg.path, cum, progressMeters).lat, pointAlongPath(leg.path, cum, progressMeters).lng]);
    src.setData({
      type: "Feature",
      properties: {},
      geometry: { type: "LineString", coordinates: passed.map(([lat, lng]) => [lng, lat]) },
    });
  }, [leg, progressMeters]);

  // -------------------------------------------------------------------------
  // Stop markers
  // -------------------------------------------------------------------------
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    for (const m of stopMarkersRef.current) m.remove();
    stopMarkersRef.current = [];

    for (const t of targets) {
      const el = document.createElement("div");
      const done = t.completed || completedIds.has(t.id);
      const isActive = t.id === activeTargetId;
      el.className = `nav-stop ${isActive ? "nav-stop-active" : ""} ${done ? "nav-stop-done" : ""}`;
      el.innerHTML =
        t.kind === "home"
          ? `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>`
          : t.kind === "dropoff"
            ? `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"/><path d="m3.3 7 8.7 5 8.7-5"/><path d="M12 22V12"/></svg>`
            : `<span>${t.stopNumber ?? ""}</span>`;
      const marker = new maplibregl.Marker({ element: el, anchor: "center" })
        .setLngLat([t.lng, t.lat])
        .addTo(map);
      stopMarkersRef.current.push(marker);
    }

    return () => {
      for (const m of stopMarkersRef.current) m.remove();
      stopMarkersRef.current = [];
    };
  }, [targets, activeTargetId, completedIds]);

  // -------------------------------------------------------------------------
  // Overview (fit active route bounds)
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (overviewRequest === 0) return;
    const map = mapRef.current;
    const currentLeg = legRef.current;
    if (!map || !currentLeg) return;
    const [[minLat, minLng], [maxLat, maxLng]] = currentLeg.bounds;
    map.fitBounds(
      [
        [minLng, minLat],
        [maxLng, maxLat],
      ],
      {
        padding: { top: 140, bottom: 300, left: 48, right: 48 },
        duration: 900,
        maxZoom: 16,
      }
    );
  }, [overviewRequest]);

  // When follow re-engages, snap back behind the vehicle
  useEffect(() => {
    if (!follow) return;
    const map = mapRef.current;
    if (!map) return;
    const s = smoothedRef.current;
    map.easeTo({
      center: [s.pos.lng, s.pos.lat],
      bearing: s.bearing,
      pitch: FOLLOW_PITCH,
      zoom: FOLLOW_ZOOM,
      duration: 600,
    });
  }, [follow]);

  // -------------------------------------------------------------------------
  // Animation loop: smooth vehicle marker + follow camera
  // -------------------------------------------------------------------------
  useEffect(() => {
    let raf = 0;
    let last = performance.now();

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = Math.min(0.1, (now - last) / 1000);
      last = now;
      const map = mapRef.current;
      const marker = vehicleRef.current;
      if (!map || !marker) return;

      const fix = fixRef.current;
      if (!fix) return;
      const s = smoothedRef.current;
      if (!s.initialized) {
        s.pos = { lat: fix.lat, lng: fix.lng };
        s.bearing = fix.heading ?? 0;
        s.initialized = true;
      }

      // Exponential smoothing toward the latest fix
      const k = 1 - Math.exp(-dt * 3.5);
      s.pos = lerpLatLng(s.pos, { lat: fix.lat, lng: fix.lng }, k);

      // Bearing: GPS heading when moving, else route bearing, else keep last
      let targetBearing = s.bearing;
      if (fix.heading !== null && (fix.speed === null || fix.speed > 1)) {
        targetBearing = fix.heading;
      } else {
        const currentLeg = legRef.current;
        if (currentLeg && !currentLeg.offline && currentLeg.path.length >= 2) {
          targetBearing = bearingAlongPath(currentLeg.path, currentLeg.cumDistances, progressRef.current);
        }
      }
      s.bearing = lerpBearing(s.bearing, targetBearing, 1 - Math.exp(-dt * 4));

      marker.setLngLat([s.pos.lng, s.pos.lat]);
      if (vehicleElRef.current) {
        vehicleElRef.current.style.transform = `rotate(${s.bearing}deg)`;
      }

      if (followRef.current && map.isStyleLoaded()) {
        map.jumpTo({
          center: [s.pos.lng, s.pos.lat],
          bearing: s.bearing,
          pitch: FOLLOW_PITCH,
          zoom: FOLLOW_ZOOM,
        });
      }
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      ref={containerRef}
      // Inline position/size beats MapLibre's `.maplibregl-map { position: relative }`
      // stylesheet rule, which would otherwise collapse the container to 0-height.
      style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}
      className={MAP_DARK_FILTER ? "nav-map-dark" : undefined}
      aria-label="Navigation map"
    />
  );
}

// ---------------------------------------------------------------------------
// 3D buildings — only when the loaded vector style exposes a building layer.
// Silently skips on raster fallback or styles without buildings.
// ---------------------------------------------------------------------------
function tryAdd3DBuildings(map: maplibregl.Map) {
  if (!ENABLE_3D_BUILDINGS) return;
  try {
    if (map.getLayer("sidekick-3d-buildings")) return;
    const style = map.getStyle();
    if (!style?.layers) return;
    const buildingLayer = style.layers.find(
      (l) =>
        (l as { "source-layer"?: string })["source-layer"] === "building" &&
        (l.type === "fill" || l.type === "fill-extrusion")
    ) as (maplibregl.LayerSpecification & { source?: string; "source-layer"?: string }) | undefined;
    if (!buildingLayer || !buildingLayer.source || !buildingLayer["source-layer"]) return;

    const before = style.layers.find((l) => l.type === "symbol")?.id;
    map.addLayer(
      {
        id: "sidekick-3d-buildings",
        type: "fill-extrusion",
        source: buildingLayer.source,
        "source-layer": buildingLayer["source-layer"],
        minzoom: 15,
        paint: {
          "fill-extrusion-color": "#1e293b",
          "fill-extrusion-opacity": 0.6,
          "fill-extrusion-height": [
            "coalesce",
            ["get", "render_height"],
            ["get", "height"],
            10,
          ] as unknown as maplibregl.ExpressionSpecification,
          "fill-extrusion-base": [
            "coalesce",
            ["get", "render_min_height"],
            ["get", "min_height"],
            0,
          ] as unknown as maplibregl.ExpressionSpecification,
        },
      } as maplibregl.LayerSpecification,
      before
    );
  } catch {
    /* 3D buildings are best-effort only */
  }
}

text:
  if (phase === "loading") {
    return (
      <FullScreenMessage>
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
        <p className="mt-3 text-sm text-muted-foreground">Loading route for {date}…</p>
      </FullScreenMessage>
    );
  }

  if (phase === "no-route") {
    return (
      <FullScreenMessage>
        <MapPin className="h-10 w-10 text-primary/50" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">No saved route</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">
          There is no route saved for {date}. Optimize and start a route from the planner first.
        </p>
        <Button onClick={() => router.push("/route")} className="mt-5 gap-2 bg-primary text-primary-foreground">
          <ArrowLeft className="h-4 w-4" /> Back to Route Planner
        </Button>
      </FullScreenMessage>
    );
  }

  if (phase === "load-error") {
    return (
      <FullScreenMessage>
        <AlertTriangle className="h-10 w-10 text-destructive" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">Could not load route</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">{loadError}</p>
        <div className="mt-5 flex gap-2">
          <Button variant="outline" onClick={() => router.push("/route")} className="border-white/10 bg-white/5">
            Back
          </Button>
          <Button onClick={() => window.location.reload()} className="bg-primary text-primary-foreground">
            Retry
          </Button>
        </div>
      </FullScreenMessage>
    );
  }

  if (phase === "not-started") {
    return (
      <FullScreenMessage>
        <AlertTriangle className="h-10 w-10 text-amber-400" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">Route not started</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">
          The saved route for {date} exists but hasn&apos;t been started. Start it to enable
          navigation and customer live-tracking.
        </p>
        {loadError && <p className="mt-2 text-sm text-destructive">{loadError}</p>}
        <div className="mt-5 flex gap-2">
          <Button variant="outline" onClick={() => router.push("/route")} className="border-white/10 bg-white/5">
            Back
          </Button>
          <Button
            onClick={startRouteAndNavigate}
            disabled={startingRoute}
            className="gap-2 bg-primary text-primary-foreground"
          >
            {startingRoute ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />}
            Start Route
          </Button>
        </div>
      </FullScreenMessage>
    );
  }

  // ---------- Start / resume confirmation ----------
  if (phase === "confirm") {
    const upcoming = targets.filter((t) => !t.completed);
    return (
      <FullScreenMessage>
        <Satellite className="h-10 w-10 text-primary" />
        <h1 className="mt-3 text-lg font-semibold text-foreground">Ready to navigate</h1>
        <p className="mt-1 max-w-xs text-center text-sm text-muted-foreground">
          {upcoming.length} stop{upcoming.length === 1 ? "" : "s"} remaining for {date}.
          {gpsStatus === "denied"
            ? " GPS permission is denied — navigation will start from Home."
            : gpsStatus === "active"
              ? " GPS locked."
              : " Waiting for GPS…"}
        </p>
        {navWarnings.length > 0 && (
          <div className="mt-3 max-w-xs rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
            {navWarnings.map((w, i) => (
              <p key={i}>⚠ {w}</p>
            ))}
          </div>
        )}
        <div className="mt-5 flex flex-col items-center gap-2">
          {resumeIndex !== null && resumeIndex > 0 && resumeIndex < upcoming.length ? (
            <>
              <Button onClick={() => beginNavigation(resumeIndex)} className="h-12 w-64 gap-2 bg-primary text-primary-foreground text-base">
                <Play className="h-5 w-5" /> Resume navigation
              </Button>
              <Button
                variant="outline"
                onClick={() => {
                  clearNavSession();
                  beginNavigation(0);
                }}
                className="h-12 w-64 gap-2 border-white/10 bg-white/5"
              >
                <RotateCcw className="h-4 w-4" /> Start from beginning
              </Button>
            </>
          ) : (
            <Button onClick={() => beginNavigation(0)} className="h-12 w-64 gap-2 bg-primary text-primary-foreground text-base">
              <Play className="h-5 w-5" /> Start navigation
            </Button>
          )}
          <Button variant="ghost" onClick={() => router.push("/route")} className="text-muted-foreground">
            Back to planner
          </Button>
        </div>
        {simulate && (
          <p className="mt-4 rounded bg-primary/10 px-2 py-1 text-[0.625rem] font-bold uppercase tracking-wider text-primary">
            Simulation mode — GPS is simulated, nothing is reported
          </p>
        )}
      </FullScreenMessage>
    );
  }

  // ---------- Completed ----------
  if (engine.status === "completed") {
    return (
      <FullScreenMessage>
        <div className="flex h-20 w-20 items-center justify-center rounded-full bg-primary/15">
          <CheckCircle2 className="h-12 w-12 text-primary" />
        </div>
